<script setup lang="ts">import { Head, Link, useForm } from '@inertiajs/vue3'; import { computed } from 'vue'; import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input'; import { Label } from '@/components/ui/label'; type Line={id:string;presentation:string;unit:string;available_quantity:string}; type Purchase={id:string;document_number:string;supplier:string;balance_amount:number;lines:Line[]}; const props=defineProps<{purchase:Purchase;now:string}>(); const form=useForm({returned_at:props.now,reason:'',lines:props.purchase.lines.map(line=>({purchase_line_id:line.id,quantity:0}))}); const selected=computed(()=>form.lines.filter(line=>Number(line.quantity)>0)); const submit=()=>form.transform(data=>({...data,lines:selected.value})).post(`/purchasing/purchases/${props.purchase.id}/returns`);</script>
<template><Head title="Devolver al proveedor" /><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header><p class="text-sm text-muted-foreground">{{ purchase.document_number }} · {{ purchase.supplier }}</p><h1 class="text-2xl font-semibold">Devolución al proveedor</h1><p class="text-sm text-muted-foreground">La confirmación retira existencias y reduce la cuenta por pagar.</p></header><form class="grid gap-5" @submit.prevent="submit"><div class="grid max-w-sm gap-2"><Label>Fecha y hora</Label><Input v-model="form.returned_at" type="datetime-local" required /></div><section class="overflow-x-auto rounded-xl border bg-card"><table class="w-full text-sm"><thead class="border-b bg-muted/40 text-left"><tr><th class="px-4 py-3">Artículo</th><th class="px-4 py-3">Disponible para devolver</th><th class="px-4 py-3">Cantidad</th></tr></thead><tbody class="divide-y"><tr v-for="(line,index) in purchase.lines" :key="line.id"><td class="px-4 py-3 font-medium">{{ line.presentation }}</td><td class="px-4 py-3">{{ line.available_quantity }} {{ line.unit }}</td><td class="px-4 py-3"><Input v-model.number="form.lines[index].quantity" class="w-40" type="number" min="0" :max="line.available_quantity" step="0.000001" /></td></tr></tbody></table></section><div class="grid gap-2"><Label>Motivo</Label><textarea v-model="form.reason" required rows="3" class="rounded-md border bg-transparent px-3 py-2 text-sm" /></div><p class="text-sm text-muted-foreground">Esta versión permite aplicar la devolución hasta el saldo pendiente. Si la compra ya fue pagada, primero debe registrarse el reintegro del proveedor.</p><div class="flex justify-end gap-2"><Button variant="outline" as-child><Link :href="`/purchasing/purchases/${purchase.id}`">Cancelar</Link></Button><Button type="submit" :disabled="form.processing||selected.length===0">Confirmar devolución</Button></div></form></main></template>
